<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { KunButton } from '@kungal/ui-vue'
import { ArrowLeft, BookOpen, Check, CheckCircle2, ChevronRight, CircleHelp, FolderOpen, Search } from 'lucide-vue-next'
import { gameCoverUrl, workCoverUrl } from '../cover-display'
import type { LibraryGame, MatchReview, WorkMetadata } from '../shared/types'

const props = defineProps<{ reviews: MatchReview[]; games: LibraryGame[]; current: MatchReview | null; choice: string; busy: boolean; includeNsfw: boolean; error: string; reloadNeeded: boolean; running: boolean }>()
const emit = defineEmits<{ select: [gameId: string]; choice: [workId: string]; detail: [work: WorkMetadata]; search: [review: MatchReview]; resolve: [skip: boolean]; later: [] }>()
const query = ref('')
const comparison = ref<HTMLElement | null>(null)
watch(() => `${props.current?.gameId}|${props.current?.reviewId}`, async () => { await nextTick(); if (comparison.value) comparison.value.scrollTop = 0 })
const gameMap = computed(() => new Map(props.games.map(game => [game.id, game])))
const game = computed(() => props.current ? gameMap.value.get(props.current.gameId) ?? null : null)
const normalize = (text: string) => text.normalize('NFKC').toLocaleLowerCase().replace(/\s+/g, ' ').trim()
const visible = computed(() => {
  const phrase = normalize(query.value)
  if (!phrase) return props.reviews
  return props.reviews.filter(review => {
    const item = gameMap.value.get(review.gameId)
    return [review.name, item?.name, review.folderPath, review.source?.folderPath,
      item?.metadata?.title, item?.metadata?.originalTitle,
      ...review.options.flatMap(option => [option.work.title, option.work.originalTitle, ...option.work.aliases])]
      .some(value => value && normalize(value).includes(phrase))
  })
})
const currentHidden = computed(() => !!props.current && !visible.value.some(review => review.gameId === props.current!.gameId))
const currentIndex = computed(() => visible.value.findIndex(review => review.gameId === props.current?.gameId))
const selectedWork = computed(() => props.current?.options.find(option => option.work.id === props.choice)?.work ?? null)
const unavailable = computed(() => props.busy || props.reloadNeeded)
const releaseDate = (work: WorkMetadata) => !work.releaseDate ? '发售日期未收录' : work.releaseDatePrecision === 'year' ? work.releaseDate.slice(0, 4) : work.releaseDatePrecision === 'month' ? work.releaseDate.slice(0, 7) : work.releaseDate
function select(id: string) { if (!unavailable.value) emit('select', id) }
function move(offset: number) { const next = visible.value[currentIndex.value + offset]; if (next) select(next.gameId) }
function choose(workId: string) { if (!unavailable.value && props.current?.sourceStatus !== 'stale') emit('choice', workId) }
</script>

<template>
  <div class="match-review-workspace" :aria-busy="busy">
    <p class="match-review-intro">对照当前关联和候选，再确认作品与版本。标题相符不代表章节或版本相同。</p>
    <div v-if="current" class="match-review-body">
      <aside class="review-queue match-review-navigation" aria-label="待核对队列">
        <div class="match-review-queue-heading"><strong class="review-queue-heading">待核对 · {{ reviews.length }}</strong><span v-if="query.trim()">显示 {{ visible.length }} 项</span></div>
        <label class="match-review-search"><Search :size="15" /><input v-model="query" :disabled="unavailable" aria-label="筛选待核对项目" placeholder="名称、目录或候选…" /></label>
        <div class="match-review-mobile-nav">
          <button type="button" :disabled="unavailable || currentIndex <= 0" aria-label="上一个核对项目" @click="move(-1)"><ArrowLeft :size="16" /></button>
          <select :value="current.gameId" :disabled="unavailable || !visible.length" aria-label="待核对项目" @change="select(($event.target as HTMLSelectElement).value)">
            <option v-if="currentHidden" :value="current.gameId">当前：{{ game?.name || current.name }}（筛选外）</option>
            <option v-for="review in visible" :key="review.gameId" :value="review.gameId">{{ gameMap.get(review.gameId)?.name || review.name }}</option>
          </select>
          <button type="button" :disabled="unavailable || currentIndex < 0 || currentIndex >= visible.length - 1" aria-label="下一个核对项目" @click="move(1)"><ChevronRight :size="16" /></button>
        </div>
        <div class="match-review-queue-list">
          <button v-for="review in visible" :key="review.gameId" type="button" :class="{ active: current.gameId === review.gameId }" :aria-current="current.gameId === review.gameId ? 'true' : undefined" :disabled="unavailable" :title="gameMap.get(review.gameId)?.name || review.name" @click="select(review.gameId)"><BookOpen :size="15" /><span>{{ gameMap.get(review.gameId)?.name || review.name }}</span><ChevronRight :size="13" /></button>
        </div>
        <p v-if="!visible.length" class="match-review-filter-empty">没有符合筛选的项目。<button type="button" :disabled="unavailable" @click="query = ''">清除筛选</button></p>
      </aside>
      <section ref="comparison" class="review-content match-review-comparison" aria-label="核对当前项目">
        <p v-if="currentHidden" class="match-review-hidden" role="status">当前项目在筛选外，仍在核对「{{ game?.name || current.name }}」。<button type="button" :disabled="unavailable" @click="query = ''">显示全部</button></p>
        <div class="review-local-game match-review-local">
          <span>本地游戏</span><h3>{{ game?.name || current.name }}</h3>
          <details :key="`${current.gameId}|${current.reviewId}`" class="match-review-source"><summary><FolderOpen :size="13" /> {{ current.source ? '首选识别目录' : '旧建议记录的目录' }} · 查看完整路径<span v-if="(current.source?.installations?.length || 0) > 1">（{{ current.source?.installations?.length }} 个安装）</span></summary><strong>书架名称：{{ game?.name || current.name }}</strong><small v-if="game && game.name !== current.name">建议记录的名称：{{ current.name }}</small><p>{{ current.source?.folderPath || current.folderPath }}</p><small v-if="current.source?.executablePath">程序：{{ current.source.executablePath }}</small><template v-if="(current.source?.installations?.length || 0) > 1"><strong>本次输入 {{ current.source?.installations?.length }} 个安装</strong><p v-for="installation in current.source?.installations" :key="installation.installationId">{{ installation.folderPath }}</p></template></details>
        </div>
        <div v-if="game?.metadata" class="review-current-work match-review-current" aria-label="当前关联"><img v-if="gameCoverUrl(game, includeNsfw)" :src="gameCoverUrl(game, includeNsfw)!" alt="" referrerpolicy="no-referrer" /><div><small>当前关联 · 确认前保留</small><strong>{{ game.metadata.title }}</strong><span>{{ releaseDate(game.metadata) }} · {{ game.metadata.developers.join(' / ') || '厂商暂未收录' }}</span></div></div>
        <div class="review-reason match-review-reason"><CircleHelp :size="15" /><p v-if="current.sourceStatus === 'stale'" role="alert">安装、名称或关联已改变，这条建议已过时。请手动搜索，或结束本次建议。</p><div v-else class="match-review-reason-copy"><p class="match-review-expanded-note">{{ current.reason }}</p><details :key="`${current.gameId}|${current.reviewId}`" class="match-review-compact-note"><summary>识别原因 · 展开核对</summary><p>{{ current.reason }}</p></details></div></div>
        <div v-if="current.sourceStatus === 'legacy'" class="review-source-note match-review-legacy"><p class="match-review-expanded-note">旧队列未记录完整来源。这里显示当前关联，请核对后再决定；目录信息不能证明候选已验证。</p><details :key="`${current.gameId}|${current.reviewId}`" class="match-review-compact-note"><summary>旧建议：来源不完整，请自行核对。</summary><p>旧队列未记录完整来源。这里显示当前关联，请核对后再决定；目录信息不能证明候选已验证。</p></details></div>
        <div v-if="current.options.length" class="review-options match-review-options" aria-label="候选作品">
          <article v-for="option in current.options" :key="option.work.id" class="review-option-row match-review-option-row">
            <button type="button" :class="['review-option', 'match-review-option', { selected: choice === option.work.id }]" :aria-pressed="choice === option.work.id" :disabled="unavailable || current.sourceStatus === 'stale'" @click="choose(option.work.id)"><img v-if="workCoverUrl(option.work, includeNsfw)" :src="workCoverUrl(option.work, includeNsfw)!" :alt="option.work.title" loading="lazy" referrerpolicy="no-referrer" /><span v-else class="match-review-cover-placeholder"><BookOpen :size="22" /></span><span class="review-option-copy match-review-option-copy"><strong>{{ option.work.title }}</strong><small v-if="option.work.originalTitle !== option.work.title">{{ option.work.originalTitle }}</small><span>{{ releaseDate(option.work) }} · {{ option.work.developers.join(' / ') || '厂商暂未收录' }}</span><em>{{ option.reason }}</em></span><span class="match-review-option-check"><Check v-if="choice === option.work.id" :size="14" /></span></button>
            <div class="match-review-option-note"><small>匹配线索，关联仍待核对</small><button type="button" class="text-button review-detail-link match-review-detail-link" :disabled="unavailable" @click="emit('detail', option.work)">查看详情</button></div>
          </article>
        </div>
        <div v-else class="review-no-options match-review-no-options"><Search :size="25" /><p>暂时没有合适的候选。</p><span>可以换一个完整名称或原名，手动搜索。</span></div>
      </section>
    </div>
    <div v-else class="small-empty review-finished match-review-finished"><CheckCircle2 :size="35" /><h3>{{ busy ? '正在保存核对结果…' : reloadNeeded ? '需要重新读取核对状态' : running ? '目前没有待核对的项目' : '待核对项目已处理完毕' }}</h3><p>{{ busy || reloadNeeded ? '请等待读取最新书架和核对队列。' : running ? '后台仍在识别其他游戏，有新的候选时会显示在这里。' : '可以返回书架查看封面与资料。' }}</p></div>
    <footer class="review-footer match-review-footer">
      <p v-if="error" class="match-review-error" role="alert">{{ error }}</p>
      <p v-if="current && !reloadNeeded" class="match-review-choice" role="status" aria-live="polite" :title="selectedWork?.title"><span>{{ busy ? '正在保存核对结果…' : selectedWork ? '将关联：' : '请选择候选，再确认关联' }}</span><strong v-if="selectedWork && !busy">{{ selectedWork.title }}</strong></p>
      <div class="match-review-actions"><button v-if="current" type="button" class="text-button match-review-manual-search" :disabled="unavailable" @click="emit('search', current)"><Search :size="14" /> 手动搜索</button><span class="match-review-action-spacer"></span><KunButton variant="light" size="sm" :disabled="busy" @click="emit('later')">{{ current ? '稍后处理' : '返回书架' }}</KunButton><KunButton v-if="current && !reloadNeeded" variant="bordered" size="sm" :disabled="busy" @click="emit('resolve', true)">{{ game?.metadata ? '保留当前关联' : '本次不关联' }}</KunButton><KunButton v-if="current || reloadNeeded" color="primary" size="sm" :disabled="!reloadNeeded && (!selectedWork || current?.sourceStatus === 'stale')" :loading="busy" @click="emit('resolve', false)"><Check v-if="!reloadNeeded" :size="14" /> {{ reloadNeeded ? '重新读取书架' : '确认关联' }}</KunButton></div>
    </footer>
  </div>
</template>

<style scoped>
