 .match-review-option-copy small,.match-review-workspace .match-review-option-copy>span,.match-review-workspace .match-review-option-copy em{font-size:12px;line-height:1.5;color:var(--muted);overflow-wrap:anywhere;font-style:normal}.match-review-workspace .match-review-option-check{width:20px;height:20px;flex:none;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;color:var(--blue)}.match-review-workspace .match-review-option.selected .match-review-option-check{border-color:var(--blue)}.match-review-workspace .match-review-option-note{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:0 11px 9px}.match-review-workspace .match-review-option-note>small{font-size:11px;color:var(--muted)}.match-review-workspace .match-review-detail-link{display:block;margin:0;font-size:12px;color:var(--blue);white-space:nowrap}.match-review-workspace .match-review-no-options{min-height:140px;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;font-size:14px;color:var(--muted)}.match-review-workspace .match-review-no-options span{font-size:12px}.match-review-workspace .match-review-footer{display:flex!important;flex-direction:column;align-items:stretch;flex:none;position:static!important;background:var(--surface);border-top:1px solid var(--line);padding:10px 0 0!important;margin:0;gap:8px!important}.match-review-workspace .match-review-error{margin:0;padding:8px 10px;border:1px solid var(--line);border-radius:7px;background:var(--hover);font-size:13px;line-height:1.5;color:var(--ink);overflow-wrap:anywhere;max-height:80px;overflow:auto}.match-review-workspace .match-review-choice{margin:0;font-size:12px;color:var(--muted);display:flex;align-items:center;gap:6px;min-width:0}.match-review-workspace .match-review-choice>span{flex:none}.match-review-workspace .match-review-choice strong{font-size:13px;color:var(--ink);font-weight:600;min-width:0;overflow:hidden;text-overflow:ellipsis;wh